/// Returns `true` iff the multiset of 3 colors can be arranged in a line
/// with no two adjacent items having the same color.
///
/// Feasibility criterion (necessary and sufficient):
/// Let `max` be the maximum count and `total` be the sum.
/// Arrangement exists iff `2 * max <= total + 1`.
pub fn check_lamp_arrangement(r: i8, g: i8, b: i8) -> bool {
    // Use a wider integer type to avoid any overflow in intermediate arithmetic.
    let (r, g, b) = (r as i32, g as i32, b as i32);

    let max = r.max(g).max(b);
    let total = r + g + b;

    2 * max <= total + 1
}

